            )
    # Note that the learning rate is already accounted for in the leaves
    # values.

    return averaged_predictions

def __sklearn_tags__(self):
    tags = super().__sklearn_tags__()
    tags.input_tags.allow_nan = True
    return tags

@abstractmethod
def _get_loss(self, sample_weight):
    pass

@abstractmethod
def _encode_y(self, y=None):
    pass  # pragma: no cover

@abstractmethod
def _encode_y_val(self, y=None):
    pass  # pragma: no cover

@property
def n_iter_(self):
    """Number of iterations of the boosting process."""
    check_is_fitted(self)
    return len(self._predictors)

def get_metadata_routing(self):
    """Get metadata routing of this object.

    Please check :ref:`User Guide <metadata_routing>` on how the routing mechanism
    works.

    Returns
    -------
    routing : MetadataRequest
        A :class:`~sklearn.utils.metadata_routing.MetadataRequest` encapsulating
        routing information.
    """
    requests = super().get_metadata_routing()
    requests.fit.add_auto_request("X_val", "y_val", "sample_weight_val")
    return requests

