import warnings
import narwhals.stable.v2 as nw
import numpy as np
from sklearn.base import is_classifier, is_clusterer, is_outlier_detector, is_regressor
from sklearn.preprocessing import LabelEncoder
from sklearn.utils import _safe_indexing
from sklearn.utils._dataframe import is_polars_df
from sklearn.utils._optional_dependencies import check_matplotlib_support
from sklearn.utils._response import _get_response_values
from sklearn.utils._set_output import _get_adapter_from_container
from sklearn.utils.deprecation import deprecated
from sklearn.utils.fixes import PETROFF_COLORS
from sklearn.utils.multiclass import type_of_target
from sklearn.utils.validation import _is_arraylike_not_scalar, _num_features, check_is_fitted

def _check_boundary_response_method(estimator, response_method):
    has_classes = hasattr(estimator, 'classes_')
    if has_classes and _is_arraylike_not_scalar(estimator.classes_[0]):
        msg = 'Multi-label and multi-output multi-class classifiers are not supported'
        raise ValueError(msg)
    if response_method == 'auto':
        if is_regressor(estimator):
            prediction_method = 'predict'
        else:
            prediction_method = ['decision_function', 'predict_proba', 'predict']
    else:
        prediction_method = response_method
    return prediction_method

def _deprecate_multiclass_colors(multiclass_colors, target_colors):
    if multiclass_colors != 'deprecated':
        warnings.warn("'multiclass_colors' was renamed to 'target_colors' in 1.10 and will be removed in 1.12.", FutureWarning)
        if target_colors is not None:
            raise ValueError("'multiclass_colors' and 'target_colors' cannot be used together. Pass `target_colors` only.")
        return multiclass_colors
    return target_colors

def _select_colors(mpl, target_colors, n_classes):
    if target_colors is None:
        if n_classes <= 10:
            target_colors = PETROFF_COLORS[:n_classes]
        else:
            target_colors = 'gist_rainbow'
    if isinstance(target_colors, str):
        if target_colors not in mpl.pyplot.colormaps():
            raise ValueError(f"When 'target_colors' is a string, it must be a valid Matplotlib colormap. Got: {target_colors}")
        cmap = mpl.pyplot.get_cmap(target_colors)
        if cmap.N < n_classes:
            raise ValueError(f"Colormap '{target_colors}' only has {cmap.N} colors, but {n_classes} classes are to be displayed. Please specify a different colormap or provide a list of colors via 'target_colors'.")
        return cmap(np.linspace(0, 1, n_classes))
    elif isinstance(target_colors, list):
        if len(target_colors) != n_classes:
            raise ValueError(f"When 'target_colors' is a list, it must be of the same length as the classes or labels to plot ({n_classes}), got: {len(target_colors)}.")
        elif any((not mpl.colors.is_color_like(col) for col in target_colors)):
            raise ValueError(f"When 'target_colors' is a list, it can only contain valid Matplotlib color names. Got: {target_colors}")
        return mpl.colors.to_rgba_array(target_colors)
    else:
        raise TypeError("'target_colors' must be a list or a str.")

class DecisionBoundaryDisplay:

    def __init__(self, *, xx0, xx1, n_classes, response, target_colors=None, xlabel=None, ylabel=None, multiclass_colors='deprecated'):
        self.xx0 = xx0
        self.xx1 = xx1
        self.n_classes = n_classes
        self.response = response
        self.target_colors = _deprecate_multiclass_colors(multiclass_colors, target_colors)
        self.xlabel = xlabel
        self.ylabel = ylabel

    @deprecated('Attribute `multiclass_colors_` was renamed to `target_colors_` in 1.10 and will be removed in 1.12. Use `target_colors_` instead.')
    @property
    def multiclass_colors_(self):
        return self.target_colors_

    def plot(self, plot_method='contourf', ax=None, xlabel=None, ylabel=None, **kwargs):
        check_matplotlib_support('DecisionBoundaryDisplay.plot')
        import matplotlib as mpl
        import matplotlib.pyplot as plt
        if plot_method not in ('contourf', 'contour', 'pcolormesh'):
            raise ValueError(f"plot_method must be 'contourf', 'contour', or 'pcolormesh'. Got {plot_method} instead.")
        if ax is None:
            _, ax = plt.subplots()
        plot_func = getattr(ax, plot_method)
        if self.n_classes == 2:
            self.surface_ = plot_func(self.xx0, self.xx1, self.response, **kwargs)
        else:
            for kwarg in ('cmap', 'colors'):
                if kwarg in kwargs:
                    warnings.warn(f"'{kwarg}' is ignored in favor of 'target_colors' in the multiclass case.")
                    del kwargs[kwarg]
            self.target_colors_ = _select_colors(mpl, self.target_colors, self.n_classes)
            if 'zorder' not in kwargs:
                kwargs['zorder'] = -1
            if self.response.ndim == 3:
                multiclass_cmaps = [mpl.colors.LinearSegmentedColormap.from_list(f'colormap_{class_idx}', [(1.0, 1.0, 1.0, 1.0), (r, g, b, 1.0)]) for class_idx, (r, g, b, _) in enumerate(self.target_colors_)]
                self.surface_ = []
                for class_idx, cmap in enumerate(multiclass_cmaps):
                    response = np.ma.array(self.response[:, :, class_idx], mask=self.response.argmax(axis=2) != class_idx)
                    self.surface_.append(plot_func(self.xx0, self.xx1, response, cmap=cmap, **kwargs))
                if plot_method == 'contour':
                    self.surface_.append(plot_func(self.xx0, self.xx1, self.response.argmax(axis=2), colors='black', zorder=-1, levels=np.arange(self.n_classes)))
            elif self.response.ndim == 2:
                if 'levels' not in kwargs:
                    if plot_method == 'contour':
                        kwargs['levels'] = np.arange(self.n_classes)
                    elif plot_method == 'contourf':
                        kwargs['levels'] = np.arange(self.n_classes + 1) - 0.5
                if plot_method == 'contour':
                    self.surface_ = plot_func(self.xx0, self.xx1, self.response, colors='black', **kwargs)
                else:
                    cmap = mpl.colors.ListedColormap(self.target_colors_)
                    self.surface_ = plot_func(self.xx0, self.xx1, self.response, cmap=cmap, **kwargs)
        if xlabel is not None or not ax.get_xlabel():
            xlabel = self.xlabel if xlabel is None else xlabel
            ax.set_xlabel(xlabel)
        if ylabel is not None or not ax.get_ylabel():
            ylabel = self.ylabel if ylabel is None else ylabel
            ax.set_ylabel(ylabel)
        self.ax_ = ax

    self.ax_ = ax
    self.figure_ = ax.figure
    return self

@classmethod
def from_estimator(cls, estimator, X, *, grid_resolution=100, eps=1.0, plot_method='contourf', response_method='auto', class_of_interest=None, target_colors=None, xlabel=None, ylabel=None, ax=None, multiclass_colors='deprecated', **kwargs):
    check_is_fitted(estimator)
    if not grid_resolution > 1:
        raise ValueError(f'grid_resolution must be greater than 1. Got {grid_resolution} instead.')
    if not eps >= 0:
        raise ValueError(f'eps must be greater than or equal to 0. Got {eps} instead.')
    possible_plot_methods = ('contourf', 'contour', 'pcolormesh')
    if plot_method not in possible_plot_methods:
        available_methods = ', '.join(possible_plot_methods)
        raise ValueError(f'plot_method must be one of {available_methods}. Got {plot_method} instead.')
    num_features = _num_features(X)
    if num_features != 2:
        raise ValueError(f'n_features must be equal to 2. Got {num_features} instead.')
    x0, x1 = (_safe_indexing(X, 0, axis=1), _safe_indexing(X, 1, axis=1))
    x0_min, x0_max = (x0.min() - eps, x0.max() + eps)
    x1_min, x1_max = (x1.min() - eps, x1.max() + eps)
    xx0, xx1 = np.meshgrid(np.linspace(x0_min, x0_max, grid_resolution), np.linspace(x1_min, x1_max, grid_resolution))
    X_grid = np.c_[xx0.ravel(), xx1.ravel()]
    if nw.dependencies.is_pandas_dataframe(X) or is_polars_df(X):
        adapter = _get_adapter_from_container(X)
        X_grid = adapter.create_container(X_grid, X_grid, columns=X.columns)
    prediction_method = _check_boundary_response_method(estimator, response_method)
    if (class_of_interest is not None and hasattr(estimator, 'classes_')) and class_of_interest not in estimator.classes_:
        raise ValueError(f'class_of_interest={class_of_interest} is not a valid label: It should be one of {estimator.classes_}')
    response, _, response_method_used = _get_response_values(estimator, X_grid, response_method=prediction_method, pos_label=class_of_interest, return_response_method_used=True)
    if response_method_used == 'predict' and hasattr(estimator, 'classes_'):
        encoder = LabelEncoder()
        encoder.classes_ = estimator.classes_
        response = encoder.transform(response)
    if class_of_interest is not None or is_regressor(estimator) or is_outlier_detector(estimator):
        n_classes = 2
    elif is_classifier(estimator) and hasattr(estimator, 'classes_'):
        n_classes = len(estimator.classes_)
    elif is_clusterer(estimator) and hasattr(estimator, 'labels_'):
        n_classes = len(np.unique(estimator.labels_))
    else:
        target_type = type_of_target(response)
        if target_type in ('binary', 'continuous'):
            n_classes = 2
        elif target_type == 'multiclass':
            n_classes = len(np.unique(response))
        else:
            raise ValueError(f"Number of classes or labels cannot be inferred from {estimator.__class__.__name__}. Please make sure your estimator follows scikit-learn's estimator API as described here: https://scikit-learn.org/stable/developers/develop.html#rolling-your-own-estimator")
    if response.ndim == 1:
        response = response.reshape(*xx0.shape)
    else:
        if is_regressor(estimator):
            raise ValueError('Multi-output regressors are not supported')
        if class_of_interest is not None:
            col_idx = np.flatnonzero(estimator.classes_ == class_of_interest)[0]
            response = response[:, col_idx].reshape(*xx0.shape)
        else:
            response = response.reshape(*xx0.shape, response.shape[-1])
    if xlabel is None:
        xlabel = X.columns[0] if hasattr(X, 'columns') else ''
    if ylabel is None:
        ylabel = X.columns[1] if hasattr(X, 'columns') else ''
    target_colors = _deprecate_multiclass_colors(multiclass_colors, target_colors)
    display = cls(xx0=xx0, xx1=xx1, n_classes=n_classes, response=response, target_colors=target_colors, xlabel=xlabel, ylabel=ylabel)
    return display.plot(ax=ax, plot_method=plot_method, **kwargs)

