{"command": "grep -n "sparse\|shrink" sklearn/neighbors/_nearest_centroid.py; sed -n '210,275p' sklearn/neighbors/_nearest_centroid.py; python - <<'PY'
import numpy as np, warnings
from scipy.sparse import csr_array, csc_array
from sklearn.neighbors import NearestCentroid, LocalOutlierFactor, KernelDensity, KNeighborsClassifier
# sparse shrink
X=np.array([[0.,0.],[2.,0.],[10.,10.],[12.,10.]])
y=np.array([0,0,1,1])
for metric in ['euclidean','manhattan']:
    try:
        z=NearestCentroid(metric=metric, shrink_threshold=1.0).fit(csc_array(X),y)
        print('sparse shrink', metric, z.centroids_)
    except Exception as e: print('sparse shrink err', metric, type(e).__name__, str(e)[:200])
# LOF contamination
for c in [0, -0.1, 0.6, 'bad']:
    try:
        LocalOutlierFactor(contamination=c).fit(X)
        print('lof c',c,'ok')
    except Exception as e: print('lof c err',c,type(e).__name__,str(e)[:180])
# KDE invalid params
for k in [None]:
    try: KernelDensity().score_samples([[0.]])
    except Exception as e: print('kde unfitted', type(e).__name__)
for Xbad in [np.ones((2,2))]:
    try: KernelDensity(bandwidth=1).fit([[0.,0.],[1.,1.]]).score_samples([[0.]])
    except Exception as e: print('kde feature mismatch', type(e).__name__, str(e)[:180])
try: KernelDensity(bandwidth=-1).fit([[0.]])
except Exception as e: print('kde bw err', type(e).__name__, str(e)[:180])
try: KernelDensity(bandwidth=1).fit([[0.],[1.]], sample_weight=[1.,-1.])
except Exception as e: print('kde sw err', type(e).__name__, str(e)[:200])
# classifier target
try: KNeighborsClassifier().fit([[0.],[1.],[2.]], [0.1,0.2,0.3])
except Exception as e: print('cls target err', type(e).__name__, str(e)[:200])
# nearest neighbors errors
from sklearn.neighbors import NearestNeighbors
from sklearn.exceptions import NotFittedError
nn=NearestNeighbors().fit([[0.],[1.]])
for n in [0,-1,1.5]:
    try: nn.kneighbors([[0.]], n_neighbors=n)
    except Exception as e: print('knn n err',n,type(e).__name__,str(e)[:180])
try: nn.kneighbors([[0.]], n_neighbors=3)
except Exception as e: print('knn too many', type(e).__name__, str(e))
try: nn.fit([[0.,1.],[1.,2.]]).kneighbors([[0.]])
except Exception as e: print('knn features', type(e).__name__, str(e)[:200])
# Radius graph invalid
from sklearn.neighbors import radius_neighbors_graph
for r in [-1, None]:
    try: radius_neighbors_graph([[0.],[1.]], r)
    except Exception as e: print('radius graph err',r,type(e).__name__,str(e)[:180])
# classification zero weights
from sklearn.neighbors import RadiusNeighborsClassifier
rc=RadiusNeighborsClassifier(radius=2, weights=lambda d: np.zeros_like(d)).fit([[0.],[1.]], [0,1])
try: rc.predict([[.5]])
except Exception as e: print('zero weight err', type(e).__name__, str(e)[:200])
PY"}

